def comps(grid):
    H,W=len(grid),len(grid[0]); seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if grid[r][c]!=grid[0][0] and (r,c) not in seen:
                stack=[(r,c)]; comp=set()
                while stack:
                    y,x=stack.pop()
                    if (y,x) in seen: continue
                    seen.add((y,x)); comp.add((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
