    for ci,ic_ in enumerate(ic):
        inp={sorted((r,c,I[r][c])) for r,c in ic_}
        found=None
        for cj,oj in enumerate(oc):
            if (cj,) in used: continue
            outp={sorted((r,c,O[r][c])) for r,c in oj}
            if outp==inp:
                found=(cj,oj); break
        if found is None:
            # partial match: try aligning
            best=None
            for cj,oj in enumerate(oc):
                if any(k in used for k in [(r,c) for r,c in oj]): continue
                outp={(r,c,O[r][c]) for r,c in oj}
                same=outp&inp
                if len(same)>len(inp)*0.5:
                    best=(cj,len(same))
            found=best
        matched.append(found)
        print(f'{name} obj {ci}: in_size={len(ic_)} -> {found[0]} size_in={matched[-1][1]}/{found[1] if isinstance(found[1],tuple) else len(found[1])}' )

