        if nm==2: return (h-p[0],p[1])
        if nm==3: return (h-p[0],h-p[1])
        if nm==4: return (p[1],p[0])
        if nm==5: return (p[1],w-p[0])
        if nm==6: return (w-p[1],p[0])
        if nm==7: return (w-p[1],w-p[0])
    for nm in range(8):
        res.add(norm([trans(p,nm) for p in pts]))
    return res
