def variants(cl):
    pts=set(cl); res=[]
    cur=list(pts); used={(p[0],p[1]) for p in cur}
    # normalize current
    def nrm(pts):
        mr=min(p[0] for p in pts); mc=min(p[1] for p in pts)
        return frozenset((p[0]-mr,p[1]-mc) for p in pts)
    cur=nrm(cur)
    for _ in range(4):
        # 4 rotations * 2 flips
        for flip in (False,True):
            v=frozenset(cur)
            res.append(v)
            if flip:
                vv=nrm({(p[0], max(p[1])-b) for p,a,b in [(p,a,0) for p in []]} ) if False else None
            # rebuild properly
            pass
        # rotate: (r,c)->(c,h-1-r)
        h=max(p[0] for p in pts)
        cur=nrm([(y,h-1-x) for x,y in pts])
    # distinct
    uniq=[]
    for v in res:
        if v not in uniq and all(not (v&u) for u in uniq): uniq.append(v)
    return uniq

def transform_shape(shapes, cl):
    mr=min(p[0] for p in cl); mc=min(p[1] for p in cl)
    return {(r-mr, c-mc) for r,c in cl}, (mr,mc)

def dihedrons(cl):
    h=max(p[0] for p in cl); w=max(p[1] for p in cl)
    res=set()
    cur=set(cl)
    for rot in range(4):
        mr=min(p[0] for p in cur); mc=min(p[1] for p in cur)
        base=frozenset((p[0]-mr,p[1]-mc) for p in cur)
        res.add(base)
        res.add(frozenset((p[0]-mr,w-1-(p[1]-mc)) for p in cur))
        cur={(y,h-1-x) for x,y in cur}
    return res

def dist_cells(A,B):
    return min(abs(r-a)+abs(c-b) for r,c in A for a,b in B)

