            for dr in range(-rh-2, rh+2):
                for dc in range(-cw-2, cw+2):
                    cells=[(pos[0]+sh[a][0]+dr, pos[1]+sh[b][1]+dc) for a,b in sh]
                    if not all(0<=r<H and 0<=c<W for r,c in cells): continue
                    if not all(I[r][c]==bg or (r,c)==pos for r,c in cells): continue
                    d_min=min(dist_cells(cells,ocells))
                    if not found and d_min>=0: found=True
                    key=(d_min,dr,dc,len(cells))
                    if found and key < (None,0,0,0): pass
        if verbose:
