def f_greedy(I,O=None,verify=True):
    H,W=len(I),len(I[0]); bg=int(Counter([x for row in I for x in row]).most_common(1)[0][0])
    OB=comps_of(I,list(bg))
    objs=[(c,cl) for c,cl in OB if len(cl)>=2]
    seeds=[(c,cl[0]) for c,cl in OB if len(cl)==1]
    out=[list(row) for row in I]
    if O is None:
        O=out
    else:
        pass
    # validate stage: compare expected vs actual when O given
