def comps(g,bg):
    R,C=g.shape; seen=set(); out=[]
    for r in range(R):
        for c in range(C):
            if g[r][c]!=bg and (r,c) not in seen:
                col=g[r][c]; st=[(r,c)]; comp=[]; seen.add((r,c))
                while st:
                    x,y=st.pop(); comp.append((x,y))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dr,y+dc
                        if 0<=nx<R and 0<=ny<C and g[nx][ny]==col and (nx,ny) not in seen:
                            seen.add((nx,ny)); st.append((nx,ny))
                out.append((col,sorted(comp)))
    return out

def dihedrons(cl):
    pts=set(cl); h=max(p[0] for p in cl); w=max(p[1] for p in cl); res=set()
    cur=list(pts)
    for rot in range(4):
        mr=min(p[0] for p in cur); mc=min(p[1] for p in cur)
        base=tuple(sorted((p[0]-mr,p[1]-mc) for p in cur))
        fbase=tuple(sorted((p[0]-mr,w-1-(p[1]-mc)) for p in cur))
        res.add(base); res.add(fbase)
        cur=[(y,h-1-x) for x,y in cur]
    return res

def variants(cl):
    # normalize all dihedral forms to canonical min-row order, remove duplicates
    s=dihedrons(cl); canon={}
    out=[]
    for v in s:
        mr=min(p[0] for p in v); mc=min(p[1] for p in v)
        kv=(mr,mc,tuple(sorted((p[0]-mr,p[1]-mc) for p in v)))
        if kv not in canon: canon[kv]=1; out.append(v)
    return out

def solve(I,O,verbose=False):
    H,W=I.shape
    bg=int(Counter(I.flatten()).most_common(1)[0][0])
    Cs=comps(I.tolist(),bg)
    objs=[(col,cl) for col,cl in Cs if len(cl)>=2]
    seeds=[(col,cl[0]) for col,cl in Cs if len(cl)==1]
    out=[list(row) for row in I]
    blocked=set((r,c) for r in range(H) for c in range(W) if I[r][c]!=bg)
    for sc,pos in sorted(seeds):
        placed=None
        for oc,ocells in objs:
            vcs=variants(ocells)
            for sh in vcs:
                rh=max(p[0] for p in sh); cw=max(p[1] for p in sh)
                for dpt in sh:
                    dr=pos[0]-dpt[0]; dc=pos[1]-dpt[1]
                    cells=[(p[0]+dr,p[1]+dc) for p in sh]
                    if any(not(0<=r<H and 0<=c<W) for r,c in cells): continue
                    if any((r,c)!=pos and (r,c) in blocked or I[r][c]!=bg for r,c in cells): continue
                    # cost: distance from copy to object (min manhattan between cell sets)
                    dm=min(abs(a-r)+abs(b-c) for a,b in cells for r,c in ocells)
