import numpy as np, os, re
from collections import Counter
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def comps(g,bg):
    seen=set(); out=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=bg and (r,c) not in seen:
                col=g[r][c]; st=[(r,c)]; comp=[]; seen.add((r,c))
                while st:
                    x,y=st.pop(); comp.append((x,y))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dr,y+dc
                        if 0<=nx<H and 0<=ny<W and g[nx][ny]==col and (nx,ny) not in seen:
                            seen.add((nx,ny)); st.append((nx,ny))
                out.append((col,sorted(comp)))
    return out
def dihedrons(nrm):
    s=set(); cur=list(nrm); hmax=max(p[0] for p in cur)
    for _ in range(4):
        mr=min(p[0] for p in cur); mc=min(p[1] for p in cur)
        mw=max(p[1] for p in cur)-mc
        s.add(tuple(sorted((p[0]-mr,p[1]-mc) for p in cur)))
        s.add(tuple(sorted((p[0]-mr,mw-p[1]+mc) for p in cur)))
        cur=[(y,hmax-1-x) for x,y in cur]
    return s

for nm in ['Demo pair 7','Demo pair 8']:
    I=np.array(G[nm+' input']); O=np.array(G[nm+' output']); H,W=I.shape
    bg=int(Counter(I.flatten()).most_common(1)[0][0])
    objs=[(int(col),cl) for col,cl in comps(I,bg) if len(cl)>=2]
    singles=[(int(col),p) for col,p in comps(I,bg) if len(p)==1]
    # added: cell -> color, only counting cells where output!=input (excludes seeds that changed)
    added={( (r,c) : int(O[r][c]) ) for r in range(H) for c in range(W)}
    changes={(r,c,int(O[r][c])) for r in range(H) for c in range(W) if I[r][c]==bg and O[r][c]!=bg}
    print(f"\n=== {nm} ===")
    hits_all=[]
    for sc,pos in sorted(singles):
        for oc,ocells in objs:
            base=tuple(sorted((p[0]-min(q[0] for q in ocells),p[1]-min(q[1] for q in ocells)) for p in ocells))
            for sh in dihedrons(base):
                sz=len(sh)
                for tr in range(-sz,H-sz):
                    for tc in range(-sz,W-sz):
                        cells={(a+tr,b+tc) for a,b in sh}
                        ok=all(p==pos or (p in changes and O[p[0]][p[1]]==sc) for p in cells)
                        if ok:
                            hits_all.append((sc,pos,oc,(tr,tc),sh,[(O[a][b2] for a,b2 in cells) if any(p==pos else True for p in cells)]) )
    # collapse identical shapes+placements
    keymap={}
    res=[]
    for h in hits_all:
        (sc,pos,oc,pl,sh,recol)=h
        k=(sc,pos,oc,pl,len(sh))
        if k not in keymap: keymap[k]=res
        res.append(h)
    print("unique placements found:")
    for k,h in list(keymap.items())[:60]:
        print(f"  seed{h[0]}@{h[1]} objcolor{h[2]} place{h[3]} shape{h[4]} n={len(h[4])}")
